url_options.body_graphql_query:
{
  issuesTrendV2(
    startDate: "${__from:date:iso}"
    endDate: "${__to:date:iso}"
    interval: DAY
    type: OPEN_ISSUES
    filterBy: { project: ${Project:json} }
  ) {
    dataPoints {
      time
      criticalSeverityValue
      highSeverityValue
      mediumSeverityValue
      lowSeverityValue
    }
  }
}

{
  issuesTrendV2(
    startDate: "${__from:date:iso}"
    endDate: "${__to:date:iso}"
    interval: DAY
    type: OPEN_ISSUES
    filterBy: { type: [THREAT_DETECTION], project: ${Project:json} }
  ) {
    dataPoints {
      time
      criticalSeverityValue
      highSeverityValue
      mediumSeverityValue
      lowSeverityValue
    }
  }
}

{
  issuesTrendV2(
    startDate: "${__from:date:iso}"
    endDate: "${__to:date:iso}"
    interval: DAY
    type: CREATED_VS_RESOLVED_ISSUES
    filterBy: { project: ${Project:json} }
  ) {
    dataPoints {
      time
      totalValue
    }
  }
}

{
  issuesTrendV2(
    startDate: "${__from:date:iso}"
    endDate: "${__to:date:iso}"
    interval: DAY
    type: CREATED_VS_RESOLVED_ISSUES
    filterBy: { project: ${Project:json} }
  ) {
    dataPoints {
      time
      totalValue
    }
  }
}

{
  issues(
    filterBy: { type: [THREAT_DETECTION], status: [OPEN, IN_PROGRESS], project: ${Project:json} }
    first: 1
  ) {
    totalCount
  }
}

{
  issues(
    filterBy: { type: [THREAT_DETECTION], status: [OPEN, IN_PROGRESS], severity: [CRITICAL], project: ${Project:json} }
    first: 1
  ) {
    totalCount
  }
}

{
  issues(
    filterBy: { type: [THREAT_DETECTION], status: [OPEN, IN_PROGRESS], severity: [HIGH], project: ${Project:json} }
    first: 1
  ) {
    totalCount
  }
}

{
  issues(
    filterBy: { type: [THREAT_DETECTION], status: [OPEN, IN_PROGRESS], severity: [MEDIUM], project: ${Project:json} }
    first: 1
  ) {
    totalCount
  }
}

{
  issues(
    filterBy: { type: [THREAT_DETECTION], status: [OPEN, IN_PROGRESS], severity: [LOW], project: ${Project:json} }
    first: 1
  ) {
    totalCount
  }
}

{
  issues(
    filterBy: { type: [THREAT_DETECTION], status: [OPEN, IN_PROGRESS], project: ${Project:json} }
    orderBy: { field: SEVERITY, direction: DESC }
    first: 500
  ) {
    nodes {
      id
      status
      severity
      createdAt
      projects { name }
      entitySnapshot {
        name
        type
        subscriptionName
        cloudPlatform
      }
      sourceRules { name }
    }
  }
}

{
